export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"tr","term":"Tam seyreltilmiş değer (FDV)","aka":["FDV","fully diluted valuation","tam seyreltilmiş piyasa değeri"],"short":"Tam seyreltilmiş değer (FDV), bir token'ın güncel fiyatının maksimum veya toplam arzla çarpılmasıyla bulunan değerdir ve tüm token'lar piyasaya çıktığında projenin ne kadar büyük görüneceğini gösterir.","body":[[["Piyasa değeri","market-capitalization"]," yalnızca şu an dolaşımdaki token'ları sayar. FDV ise ekibe, yatırımcılara, ekosistem fonuna ayrılmış ve henüz kilidi açılmamış token'ları da hesaba katar. Formül: FDV = fiyat x toplam (veya maksimum) arz."],"Piyasa değeri ile FDV arasındaki fark büyükse, ileride çok sayıda yeni token'ın piyasaya gelmesi beklenir. Bu token'lar satışa çıkarsa mevcut fiyatı korumak için daha fazla talep gerekir. Yeni listelenen birçok token, dolaşımda arzın küçük bir kısmıyla ama yüksek FDV ile işleme başlar.",["Veri siteleri FDV'yi farklı tanımlayabilir: bazıları maksimum arzı, bazıları mevcut toplam arzı kullanır. ",["Bitcoin","bitcoin"]," gibi arzı neredeyse tamamen dolaşımda olan coinlerde iki değer birbirine yakındır."]],"example":["Bir token 2 ",["USDT","usdt"],"'den işlem görüyor, ",["dolaşımdaki arz","circulating-supply"]," 100 milyon, toplam arz 1 milyar olsun. Piyasa değeri 2 x 100.000.000 = 200 milyon USDT, FDV ise 2 x 1.000.000.000 = 2 milyar USDT'dir. Yani arzın yalnızca yüzde 10'u dolaşımda. Kalan 900 milyon token önümüzdeki yıllarda açıldığında aynı FDV'yi korumak için fiyatın sabit kalması gerekir, ama bu kez piyasa değeri 2 milyar USDT'ye ulaşmalıdır; bunun için on kat daha fazla sermaye girmesi gerekir."],"mistakes":["Yalnızca düşük piyasa değerine bakıp FDV'si çok yüksek bir token'ı ucuz sanmak.","Token kilit açılma takvimini kontrol etmeden uzun vadeli pozisyon almak.","Farklı sitelerdeki FDV rakamlarının neden farklı olduğunu sorgulamadan karşılaştırmak."],"faq":[{"q":"FDV ile piyasa değeri arasındaki fark nedir?","a":"Piyasa değeri dolaşımdaki arzı, FDV ise toplam veya maksimum arzı kullanır. Aradaki fark, ileride piyasaya girecek token miktarının bir göstergesidir."},{"q":"Yüksek FDV kötü bir işaret mi?","a":"Tek başına değil, ama dolaşımdaki arz düşükken FDV çok yüksekse gelecekteki kilit açılmaları fiyat üzerinde satış baskısı yaratabilir. Kilit takvimini ve dağılımı birlikte incelemek gerekir."}],"title":"FDV nedir? Tam seyreltilmiş değer anlamı","description":"FDV'nin ne olduğunu, piyasa değerinden farkını ve kilitli token'ların gelecekteki satış baskısını nasıl gösterdiğini öğrenin.","related":[["market-capitalization","Piyasa değeri (market cap)","Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır."],["circulating-supply","Dolaşımdaki arz (circulating supply)","Dolaşımdaki arz, bir kripto paranın şu anda piyasada serbestçe alınıp satılabilen, kilitli veya rezervde tutulmayan coin ya da token miktarıdır."],["token-unlock","Token kilit açılımı (token unlock)","Token kilit açılımı (token unlock), ekip, yatırımcılar veya ekosistem fonu için önceden kilitlenmiş token'ların belirlenmiş bir takvime göre serbest bırakılıp alınıp satılabilir hale gelmesidir."],["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"tr","term":"Kripto madenciliği (mining)","aka":["madencilik","mining","Bitcoin madenciliği"],"short":"Kripto madenciliği, iş ispatı kullanan blockchain'lerde özel donanımlarla hesaplama yapılarak işlemlerin bloklara eklenmesi ve karşılığında yeni basılan coin ile işlem ücretlerinin kazanılması sürecidir.","body":[["Madenciler bekleyen işlemleri toplar, bir blok adayı oluşturur ve iş ispatı bulmacasını çözmeye çalışır. İlk çözen madenci bloğu ağa yayınlar ve blok ödülünü alır. ",["Bitcoin","bitcoin"],"'de bu ödül Nisan 2024'ten beri blok başına 3,125 BTC artı işlem ücretleridir."],"Bitcoin madenciliği bugün ASIC adı verilen, yalnızca bu işi yapan cihazlarla yapılır. Tek bir madencinin blok bulma şansı çok düşük olduğu için çoğu madenci havuzlara (mining pool) katılır ve gücü oranında düzenli ödeme alır.","Kârlılığı belirleyen başlıca etkenler elektrik fiyatı, cihaz verimliliği, ağ zorluğu ve coin fiyatıdır. Halving'ler ödülü yarıya indirdiği için verimsiz cihazlar zamanla kâr edemez hale gelir. Madencilikle ilgili yasal ve vergisel kurallar ülkeden ülkeye değişir."],"example":"Saatte 3,5 kWh elektrik harcayan bir ASIC cihazınız olduğunu varsayalım. Günde 24 saat çalışırsa 84 kWh tüketir. Elektriğin kWh başına 0,10 dolar olduğu bir yerde günlük elektrik maliyeti 8,4 dolardır. Havuzdan gelen günlük gelir 10 dolar ise brüt kâr 1,6 dolardır; havuz yüzde 2 komisyon alırsa gelir 9,8 dolara iner ve kâr 1,4 dolara düşer. Coin fiyatı yüzde 20 gerilerse gelir 7,84 dolara iner ve cihaz zararına çalışmaya başlar.","mistakes":["Elektrik maliyetini ve cihazın değer kaybını hesaba katmadan kârlılık hesabı yapmak.","Bulut madencilik vaat eden ve sabit yüksek getiri garanti eden platformlara güvenmek.","Bir sonraki halving'in gelir üzerindeki etkisini planlamaya dahil etmemek."],"faq":[{"q":"Evde kripto madenciliği yapılabilir mi?","a":"Teknik olarak mümkündür, ancak Bitcoin'de rekabet büyük endüstriyel tesislerle yapılır. Ev elektrik tarifesiyle çoğu durumda maliyet gelirden yüksek çıkar."},{"q":"Ethereum madenciliği hâlâ yapılıyor mu?","a":"Hayır. Ethereum Eylül 2022'de hisse ispatına geçtiği için ETH madenciliği sona erdi. ETH artık staking ile güvence altına alınıyor."}],"title":"Kripto madenciliği nedir? Mining nasıl çalışır?","description":"Kripto madenciliğinin nasıl çalıştığını, madencilik havuzlarını ve elektrik, zorluk ve halving'in kârlılığı nasıl etkilediğini öğrenin.","related":[["proof-of-work","İş ispatı (Proof of Work, PoW)","İş ispatı (Proof of Work, PoW), madencilerin zor bir matematik bulmacasını çözmek için bilgi işlem gücü harcadığı ve bulmacayı ilk çözenin yeni bloğu ekleyip ödül kazandığı bir blockchain uzlaşma mekanizmasıdır."],["hash-rate","Hash oranı (hash rate)","Hash oranı, iş ispatı (proof of work) kullanan bir ağda madencilerin saniyede yaptığı toplam hash hesaplama sayısıdır ve ağın işlem gücünü ve güvenliğini gösterir."],["bitcoin-halving","Bitcoin halving (yarılanma)","Bitcoin halving (yarılanma), yaklaşık her dört yılda bir, yani her 210.000 blokta bir, madencilere verilen blok ödülünün kod gereği yarıya indirildiği olaydır."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"tr","term":"Validatör (doğrulayıcı)","aka":["doğrulayıcı","validator","validatör düğümü"],"short":"Validatör (doğrulayıcı), hisse ispatı kullanan bir blockchain'de coin stake ederek yeni blokları öneren, diğer blokları doğrulayan ve bu iş karşılığında ödül alan düğüm operatörüdür.","body":["Validatör, ağın yazılımını sürekli çalışır halde tutan bir sunucu ve ona bağlı kilitli coinlerden oluşur. Sırası geldiğinde blok önerir, diğer zamanlarda başkalarının bloklarına oy (attestation) vererek onları onaylar.",[["Ethereum","ethereum"],"'da tek bir validatör için 32 ETH gerekir. Hatalı veya kötü niyetli davranış slashing cezasıyla sonuçlanabilir; sunucunun sık sık kapalı olması ise küçük ceza ve kaçırılan ödüller demektir. Bu yüzden iyi bir validatör kesintisiz çalışma, güncel yazılım ve güvenli anahtar yönetimi gerektirir."],["Kendi validatörünüzü çalıştırmak yerine coinlerinizi bir validatöre devredebilir (delegation), borsaların ",["staking","staking"]," hizmetlerini veya ",["likit staking","liquid-staking"]," protokollerini kullanabilirsiniz. Bu durumda hizmet sağlayıcı ödülden komisyon alır ve operasyon riskinin bir kısmını siz de taşırsınız."]],"example":"Ethereum'da bir validatör çalıştırmak için 32 ETH stake ettiğinizi ve ağın yıllık ödül oranının yaklaşık yüzde 3 olduğunu varsayalım. Bir yılda yaklaşık 32 x 0,03 = 0,96 ETH kazanırsınız. Sunucunuz yıl boyunca yüzde 5 oranında çevrimdışı kalırsa o süredeki ödülleri kaçırır ve küçük cezalar alırsınız; kazanç kabaca 0,9 ETH civarına iner. Aynı 32 ETH'yi yüzde 10 komisyonla bir hizmete devretseniz 0,96 ETH'nin 0,096'sı komisyona gider ve size yaklaşık 0,864 ETH kalır.","mistakes":["Validatör anahtarlarını aynı anda iki farklı makinede çalıştırıp çift imza nedeniyle slashing cezası almak.","Bir validatöre devretmeden önce komisyon oranını ve çalışma süresi geçmişini kontrol etmemek.","Validatör ödüllerini sabit sanmak; oran ağdaki toplam stake'e ve işlem hacmine göre değişir."],"faq":[{"q":"Validatör olmak için ne kadar coin gerekir?","a":"Ağdan ağa değişir. Ethereum'da bir validatör için 32 ETH gerekir; diğer birçok ağda ise küçük tutarlarla bir validatöre delegasyon yapılabilir."},{"q":"Validatör ile madenci arasındaki fark nedir?","a":"Madenci iş ispatı ağlarında hesaplama gücüyle, validatör ise hisse ispatı ağlarında stake edilmiş coinlerle blok üretir. İkisi de dürüst çalıştığında ödül kazanır."}],"title":"Validatör nedir? Blockchain'de doğrulayıcı ne yapar?","description":"Validatörün ne yaptığını, Ethereum'da neden 32 ETH gerektiğini ve slashing ile delegasyonun nasıl çalıştığını öğrenin.","related":[["proof-of-stake","Hisse ispatı (Proof of Stake, PoS)","Hisse ispatı (Proof of Stake, PoS), yeni blokları üretme ve doğrulama hakkının, ağın coinini teminat olarak kilitleyen (stake eden) validatörlere verildiği bir blockchain uzlaşma mekanizmasıdır."],["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["restaking","Restaking (yeniden stake etme)","Restaking, zaten stake edilmiş ETH'yi veya likit staking token'larını başka hizmetlerin güvenliğini sağlamak için ikinci kez taahhüt ederek ek ödül kazanmayı amaçlayan bir yapıdır."],["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"tr","term":"İşlem çifti (parite)","aka":["parite","trading pair","işlem paritesi"],"short":"İşlem çifti (parite), bir borsada birbirine karşı alınıp satılan iki varlığı gösterir; BTC/USDT paritesinde BTC alınan veya satılan varlık, USDT ise fiyatın ifade edildiği birimdir.","body":[["Paritedeki ilk varlığa baz varlık, ikinciye kote (karşı) varlık denir. ",["BTC","bitcoin"],"/",["USDT","usdt"]," paritesinde fiyat 60.000 ise 1 BTC almak için 60.000 USDT ödersiniz. ",["ETH","ethereum"],"/BTC paritesinde ise ETH'nin fiyatı BTC cinsinden görünür."],["Borsalar genellikle USDT, ",["USDC","usdc"],", BTC ve yerel para birimleri (örneğin TRY) karşısında pariteler sunar. Aynı coin farklı paritelerde farklı likiditeye sahip olabilir. Genellikle USDT paritesi en derin emir defterine sahiptir; küçük paritelerde makas genişleyebilir."],["Elinizde olmayan bir kote varlıkla doğrudan işlem yapamazsınız. Örneğin elinizde TRY varsa ve coin yalnızca USDT paritesinde listelenmişse, önce TRY/USDT ile USDT almanız gerekir. Bu iki adımlı yol, iki kez ",["işlem ücreti","gas-fee"]," ve makas maliyeti demektir."]],"example":"ETH/USDT paritesinde fiyat 3.000, BTC/USDT paritesinde 60.000 olsun. Bu durumda ETH/BTC paritesinin yaklaşık 3.000 / 60.000 = 0,05 olması beklenir. Elinizde 0,1 BTC var ve ETH almak istiyorsunuz. ETH/BTC paritesinden doğrudan alırsanız yaklaşık 2 ETH alır ve tek ücret ödersiniz. Önce BTC'yi USDT'ye çevirip sonra ETH alırsanız iki kez yüzde 0,1 ücret ödersiniz; ama ETH/BTC paritesinin likiditesi düşükse makas farkı bu ek ücretten daha pahalıya gelebilir.","mistakes":["BTC paritesinde gösterilen fiyatı USDT fiyatı sanmak.","Likiditesi düşük bir pariteyi seçip daha geniş makas ve kayma ödemek.","Ara dönüşümlerde ödediğiniz ek ücretleri ve makas maliyetini hesaba katmamak."],"faq":[{"q":"BTC/USDT ne anlama gelir?","a":"Bitcoin'in Tether'in USDT stablecoin'i karşısında alınıp satıldığı pariteyi gösterir. Gösterilen fiyat 1 BTC'nin kaç USDT ettiğidir."},{"q":"Hangi pariteyi seçmeliyim?","a":"Genellikle en yüksek hacimli ve en dar makaslı parite daha düşük maliyetlidir. Elinizdeki varlık ve kaç dönüşüm adımı gerektiği de seçimi etkiler."}],"title":"İşlem çifti (parite) nedir? BTC/USDT ne demek?","description":"Kripto borsalarında işlem çiftinin ne olduğunu, baz ve kote varlık farkını ve doğru pariteyi seçmenin maliyete etkisini öğrenin.","related":[["spot-trading","Spot işlem (spot trading)","Spot işlem, bir kripto parayı o anki piyasa fiyatından alıp satarak varlığın kendisine anında sahip olduğunuz, kaldıraç ve vade içermeyen temel alım satım türüdür."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"İlk spot işlemin: 100'den 0.002 BTC'ye"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"tr","term":"OCO emri (biri diğerini iptal eder)","aka":["OCO","OCO emir","one-cancels-the-other"],"short":"OCO emri (one-cancels-the-other), birbirine bağlı iki emirden oluşan ve biri gerçekleştiği anda diğerinin otomatik olarak iptal edildiği bir emir türüdür; genellikle kâr al ve zarar durdur emrini birlikte koymak için kullanılır.","body":[["Tipik bir OCO'da pozisyonun üstünde bir limit satış (kâr al) ve altında bir stop-limit satış (zarar durdur) emri bulunur. Fiyat yukarı giderse ",["kâr al emri","take-profit"]," dolar ve stop emri iptal edilir; fiyat aşağı giderse stop tetiklenir ve kâr al emri iptal edilir."],"OCO'nun yararı, aynı varlık için iki ayrı satış emri koyduğunuzda ortaya çıkabilecek sorunu çözmesidir. İki bağımsız emirle, biri dolduktan sonra diğeri defterde kalıp istemediğiniz bir işlemi tetikleyebilir. OCO bu riski ortadan kaldırır.","OCO özellikle spot piyasada yaygındır; vadeli işlemlerde aynı işlev genellikle pozisyona bağlı TP/SL ayarlarıyla sağlanır. Emir ekranındaki alan adları ve fiyat kuralları borsadan borsaya değişebilir."],"example":["Elinizde 2 ",["ETH","ethereum"]," var ve fiyat 3.000 ",["USDT","usdt"],". Bir OCO satış emri kuruyorsunuz: limit satış 3.300 USDT'de, stop tetiği 2.850, stop-limit fiyatı 2.840 USDT. Fiyat 3.300'e çıkarsa 2 ETH 6.600 USDT'ye satılır, 600 USDT kâr edersiniz ve stop emri otomatik iptal olur. Fiyat önce 2.850'ye düşerse stop tetiklenir, 2 ETH en kötü 2.840'tan satılır ve kayıp en fazla 320 USDT olur; kâr al emri ise iptal edilir. Bu kurulumda ",["risk-ödül oranı","risk-reward-ratio"]," yaklaşık 1:1,9'dur."],"mistakes":["OCO yerine iki ayrı satış emri koyup birinin dolmasından sonra diğerini iptal etmeyi unutmak.","OCO'nun stop tarafının da stop-limit olduğunu ve hızlı düşüşte dolmayabileceğini bilmemek.","Kâr al ve stop fiyatlarını mevcut fiyatın yanlış tarafına girip emrin reddedilmesine neden olmak."],"faq":[{"q":"OCO emri ne işe yarar?","a":"Aynı pozisyon için hem kâr hedefi hem de zarar sınırı belirlemenizi sağlar. Biri gerçekleşince diğeri iptal edildiği için çift işlem riski olmaz."},{"q":"OCO emri vadeli işlemlerde kullanılır mı?","a":"Bazı borsalarda vardır, ancak vadeli işlemlerde aynı amaç genellikle pozisyona bağlı TP/SL ayarlarıyla karşılanır."}],"title":"OCO emri nedir? Nasıl kullanılır?","description":"OCO emrinin nasıl çalıştığını, kâr al ve zarar durdur emirlerini nasıl birbirine bağladığını ve olası tuzaklarını öğrenin.","related":[["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["risk-reward-ratio","Risk-ödül oranı (Risk-reward ratio)","Risk-ödül oranı, bir işlemde zarar durdur seviyesine kadar göze aldığınız olası kaybı, kâr al hedefindeki olası kazançla karşılaştıran orandır."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Piyasa, limit, iptal: Her biri neyi çözer?"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"tr","term":"Sadece yapıcı (post-only) emir","aka":["post-only","post only","yalnızca maker emri","maker only"],"short":"Sadece yapıcı (post-only) emir, yalnızca emir defterine eklenebiliyorsa kabul edilen ve anında eşleşip taker olacaksa iptal edilen bir limit emir seçeneğidir; amacı her zaman maker ücreti ödemektir.","body":[["Normal bir ",["limit emir","limit-order"],", fiyatı mevcut karşı emirlerle örtüşüyorsa hemen eşleşir ve ",["taker ücreti","maker-taker-fees"]," öder. Post-only seçeneği işaretliyse borsa bu durumda emri reddeder veya iptal eder. Böylece emriniz ya defterde bekler ya da hiç girilmez."],"Bu seçenek, maker ve taker ücretleri arasındaki farkın önemli olduğu sık işlem yapan kullanıcılar, piyasa yapıcılar ve algoritmik stratejiler için kullanışlıdır. Bazı borsalarda belirli kademelerde maker ücreti sıfır veya negatif (rebate) olabilir; bu oranlar borsaya göre değişir.","Dezavantajı, hızlı hareket eden piyasada emrinizin sürekli reddedilebilmesi ve işlemi kaçırabilmenizdir. Post-only, hızın değil maliyetin öncelikli olduğu durumlar içindir."],"example":[["BTC","bitcoin"],"/",["USDT","usdt"],"'de en iyi alış 60.000, en iyi satış 60.010 USDT. 60.010'dan post-only alış emri verirseniz, bu fiyat defterdeki satış emriyle anında eşleşeceği için emir iptal edilir. 60.000'den post-only alış emri verirseniz emir defterde bekler. Diyelim ki emriniz dolar ve 0,5 BTC alırsınız: işlem değeri 30.000 USDT. Maker ücreti yüzde 0,02 ise 6 USDT, taker ücreti yüzde 0,05 olsaydı 15 USDT ödeyecektiniz. Ayda 20 böyle işlem yapan biri için fark 180 USDT eder."],"mistakes":["Post-only emrin reddedildiğini fark etmeyip pozisyon açıldığını sanmak.","Hızlı piyasada post-only fiyatını sürekli karşı tarafa yakın koyup emrin tekrar tekrar iptal edilmesine yol açmak.","Ücret tasarrufu için post-only kullanırken kaçırılan fırsatların maliyetini hesaba katmamak."],"faq":[{"q":"Post-only emrim neden iptal edildi?","a":"Emrin fiyatı mevcut karşı emirlerle eşleşecek seviyedeydi, yani taker olacaktı. Post-only kuralı gereği borsa emri defterde beklemek yerine iptal etti."},{"q":"Post-only her zaman daha ucuz mu?","a":"Dolduğunda maker ücreti ödediğiniz için genellikle evet. Ancak emir hiç dolmazsa veya istediğiniz fiyatı kaçırırsanız dolaylı bir maliyet oluşabilir."}],"title":"Post-only emir nedir? Maker ücretiyle ilişkisi","description":"Post-only emrin nasıl çalıştığını, neden iptal edilebildiğini ve maker ücretiyle nasıl tasarruf sağladığını örnekle öğrenin.","related":[["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["time-in-force","Emir geçerlilik süresi (GTC, IOC, FOK)","Emir geçerlilik süresi (time in force), bir emrin ne kadar süre aktif kalacağını ve dolmayan kısmına ne olacağını belirleyen ayardır; en yaygın seçenekler GTC, IOC ve FOK'tur."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Piyasa, limit, iptal: Her biri neyi çözer?"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"tr","term":"Maker ve taker ücretleri","aka":["maker ücreti","taker ücreti","yapıcı-alıcı komisyonu"],"short":"Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır.","body":[["Emir defterinde hemen eşleşmeyen bir ",["limit emri","limit-order"]," verdiğinizde emriniz defterde bekler ve başkalarının işlem yapabileceği ",["likidite","liquidity"]," oluşturur. Bu durumda maker sayılırsınız. ",["Piyasa emri","market-order"]," ya da mevcut fiyattan hemen eşleşen bir limit emri verdiğinizde ise defterdeki bir emri tüketirsiniz ve taker olursunuz."],["Borsalar genellikle maker ücretini taker ücretinden düşük tutar, çünkü derin ve dar makaslı bir defter herkesin işine yarar. Bazı borsalarda ve yüksek hacimli VIP seviyelerinde maker ücreti sıfır, hatta negatif olabilir; yani komisyon yerine küçük bir geri ödeme alırsınız. Oranlar spot ile ",["vadeli işlemler","futures-contract"]," arasında ve borsadan borsaya değişir, güncel tabloyu borsanızın ücret sayfasından kontrol edin."],["Sık işlem yapan biri için bu fark ciddi bir maliyet kalemidir. ",["Post-only","post-only-order"]," seçeneği, emrinizin taker olarak eşleşmesini engeller ve deftere yalnızca maker olarak girmesini sağlar."]],"example":["Varsayalım ki maker ücreti yüzde 0,02, taker ücreti yüzde 0,05. 10.000 ",["USDT","usdt"]," değerinde bir pozisyonu piyasa emriyle açıp yine piyasa emriyle kapatırsanız toplam 10.000 × 0,0005 × 2 = 10 USDT komisyon ödersiniz. Aynı işlemi iki limit emriyle maker olarak yaparsanız 10.000 × 0,0002 × 2 = 4 USDT ödersiniz. Ayda 50 böyle işlemde aradaki fark 300 USDT eder."],"mistakes":["Limit emri verdiğiniz için her zaman maker ücreti ödeyeceğinizi sanmak; fiyatınız karşı taraftaki en iyi emre ulaşıyorsa emir anında eşleşir ve taker sayılır.","Küçük görünen ücret farkını hesaba katmayıp sık işlemde kârın önemli bir kısmını komisyona kaptırmak.","Spot ve vadeli işlemlerde ücret oranlarının aynı olduğunu varsaymak."],"faq":[{"q":"Maker mı taker mı daha ucuz?","a":"Çoğu borsada maker ücreti daha düşüktür, çünkü maker emirleri deftere likidite ekler. Kesin oranlar borsaya, ürüne ve hesap seviyenize göre değişir."},{"q":"Limit emri her zaman maker mıdır?","a":"Hayır. Limit emri anında defterdeki bir emirle eşleşirse taker olarak işlem görür. Sadece maker olmak istiyorsanız post-only seçeneğini kullanın."},{"q":"Negatif maker ücreti ne demek?","a":"Bazı borsalar belirli seviyelerde maker emirlerinden komisyon almak yerine küçük bir geri ödeme yapar. Bu genellikle yüksek hacimli kullanıcılar ve piyasa yapıcılar için geçerlidir."}],"title":"Maker ve taker ücreti nedir? Kripto komisyonları","description":"Maker ve taker ücretlerinin farkını, hangi emrin hangi ücreti ödediğini ve komisyonu nasıl düşüreceğinizi öğrenin.","related":[["post-only-order","Sadece yapıcı (post-only) emir","Sadece yapıcı (post-only) emir, yalnızca emir defterine eklenebiliyorsa kabul edilen ve anında eşleşip taker olacaksa iptal edilen bir limit emir seçeneğidir; amacı her zaman maker ücreti ödemektir."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["market-order","Piyasa emri (market order)","Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir."],["vip-tier","VIP ücret seviyesi","VIP ücret seviyesi, borsaların 30 günlük işlem hacminize veya hesap bakiyenize göre sizi kademelere ayırıp daha yüksek kademede daha düşük maker ve taker ücreti uyguladığı sistemdir."],["referral-code","Referans kodu (komisyon iadesi)","Referans kodu, bir borsaya kaydolurken girilen ve sizi davet eden kişi veya ortakla eşleştiren; çoğu zaman işlem ücretlerinizin bir kısmının size geri ödenmesini sağlayan davet kodudur."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Ekrandaki fiyat neden benim gerçekleşen fiyatım değil?"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"tr","term":"Bakım teminatı (Maintenance margin)","aka":["bakım marjini","maintenance margin","sürdürme teminatı"],"short":"Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar.","body":[["Bakım teminatı, pozisyonun nominal değerinin borsanın belirlediği bakım teminatı oranıyla çarpılmasıyla bulunur. Bu oran genellikle ",["başlangıç teminatı","initial-margin"]," oranından çok daha düşüktür ve pozisyon büyüdükçe kademeli olarak artar."],["Pozisyonunuz zarar ettikçe teminat bakiyeniz azalır. İşaret fiyatına göre hesaplanan teminatınız bakım teminatına eşit veya altına düştüğü anda borsa pozisyonu tasfiye etmeye başlar. Bazı borsalar bundan önce ",["teminat uyarısı","margin-call"]," (margin call) bildirimi gönderir, ama buna güvenmek yerine ",["likidasyon","liquidation"]," fiyatını kendiniz takip etmelisiniz."],"Tasfiye sırasında kalan teminatın bir kısmı likidasyon ücreti olarak alınabilir veya sigorta fonuna aktarılabilir. Bakım teminatı oranları ve kademeleri her kontrat için farklıdır; ayrıntıları borsanızın risk limiti veya kontrat şartname sayfasında bulabilirsiniz."],"example":[["BTC","bitcoin"]," 60.000 ",["USDT","usdt"]," iken 0,2 BTC long açıyorsunuz; nominal değer 12.000 USDT ve 10x kaldıraçla teminat 1.200 USDT. Bakım teminatı oranı yüzde 0,5 ise bakım teminatı yaklaşık 60 USDT'dir. Tasfiyeden önce dayanabileceğiniz zarar yaklaşık 1.140 USDT'dir. 0,2 BTC'lik pozisyonda bu, fiyatın 5.700 USDT düşmesine denk gelir; ",["likidasyon fiyatı","liquidation-price"]," yaklaşık 54.300 USDT olur, ücretler bu seviyeyi biraz yukarı çeker."],"mistakes":["Likidasyonun teminat sıfıra inince olduğunu sanmak; bakım seviyesine inince başlar.","Büyük pozisyonlarda bakım teminatı oranının kademeli olarak arttığını bilmemek.","Teminat uyarısının her zaman zamanında geleceğine güvenmek."],"faq":[{"q":"Bakım teminatının altına düşersem ne olur?","a":"Borsa pozisyonunuzu kısmen veya tamamen tasfiye eder. Bazı borsalar önce pozisyonu küçülterek riski azaltmaya çalışır."},{"q":"Bakım teminatını artırabilir miyim?","a":"Oranı değiştiremezsiniz, ama izole pozisyona ek teminat ekleyerek ya da pozisyonu küçülterek likidasyon fiyatını uzaklaştırabilirsiniz."}],"title":"Bakım teminatı (maintenance margin) nedir?","description":"Bakım teminatının nasıl hesaplandığını, likidasyonu ne zaman tetiklediğini ve tasfiye fiyatına etkisini öğrenin.","related":[["initial-margin","Başlangıç teminatı (Initial margin)","Başlangıç teminatı, kaldıraçlı bir pozisyonu açabilmek için hesabınızda bulunması ve pozisyona bağlanması gereken asgari teminat tutarıdır."],["liquidation-price","Likidasyon fiyatı (Liquidation price)","Likidasyon fiyatı, kaldıraçlı bir pozisyonun teminatının bakım seviyesine indiği ve borsanın pozisyonu zorla kapatmaya başladığı işaret fiyatı seviyesidir."],["margin-call","Teminat tamamlama çağrısı (Margin call)","Teminat tamamlama çağrısı (margin call), kaldıraçlı pozisyonunuzun teminatı bakım seviyesine yaklaştığında borsanın sizi ek teminat yatırmanız veya pozisyonu küçültmeniz için uyarmasıdır."],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Teminatınız sıfıra ulaşmadan önce pozisyonunuz neden kapatılabilir?"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"tr","term":"Sadece azalt emri (Reduce-only order)","aka":["reduce-only","yalnızca azalt","sadece pozisyon azalt"],"short":"Sadece azalt emri (reduce-only), yalnızca mevcut bir pozisyonu küçültebilen ve hiçbir durumda yeni pozisyon açamayan veya mevcut pozisyonu büyütemeyen bir vadeli işlem emri seçeneğidir.","body":[["Normal bir satış emri, long pozisyonunuzdan büyükse fazlası yeni bir ",["short pozisyon","long-and-short"]," açar. Reduce-only seçeneği işaretliyse emir en fazla mevcut ",["pozisyon büyüklüğü","position-sizing"]," kadar işlem görür; pozisyon kapandıktan sonra kalan kısım iptal edilir veya küçültülür. Böylece istemeden ters yönde pozisyon açmazsınız."],["Bu özellik özellikle kâr al ve zarar durdur emirlerinde önemlidir. Örneğin pozisyonunuzu manuel olarak kapattıktan sonra eski ",["kâr al emri","take-profit"]," defterde kalmışsa ve reduce-only değilse, fiyat oraya geldiğinde yeni bir pozisyon açabilir. Reduce-only bu riski ortadan kaldırır."],["Birçok borsada pozisyona bağlı kâr al ve stop emirleri varsayılan olarak reduce-only çalışır, ama bağımsız limit emirlerinde seçeneği sizin işaretlemeniz gerekebilir. ",["Hedge","hedging"]," modunda long ve short ayrı tutulduğu için davranış biraz farklıdır; borsanızın emir ekranındaki açıklamayı kontrol edin."]],"example":[["ETH","ethereum"]," ",["perpetual","perpetual-futures"]," kontratında 3 ETH long pozisyonunuz var. 2.800 USDT'ye 3 ETH'lik kâr al limit emri koydunuz, ama fiyat 2.750'ye gelince pozisyonun 2 ETH'sini manuel olarak kapattınız. Kalan pozisyon 1 ETH. Kâr al emri reduce-only değilse fiyat 2.800'e çıktığında 3 ETH satar: 1 ETH pozisyonunuzu kapatır ve 2 ETH yeni short açar. Reduce-only işaretliyse yalnızca 1 ETH satılır ve emrin kalanı iptal edilir."],"mistakes":["Pozisyonu manuel küçülttükten sonra eski kâr al veya stop emirlerini kontrol etmemek.","Bağımsız limit emirlerinin de otomatik olarak reduce-only olduğunu varsaymak.","Reduce-only emrin pozisyon yoksa beklemede kalacağını sanmak; çoğu borsada iptal edilir veya reddedilir."],"faq":[{"q":"Reduce-only ne işe yarar?","a":"Emrin yalnızca mevcut pozisyonu küçültmesini, asla yeni pozisyon açmamasını garanti eder. Böylece kâr al veya stop emirleri istemeden ters pozisyona dönüşmez."},{"q":"Reduce-only emir ne zaman reddedilir?","a":"Kapatılacak bir pozisyon yoksa veya emir yönü pozisyonu büyütecek yöndeyse borsa emri reddeder ya da iptal eder."}],"title":"Reduce-only (sadece azalt) emri nedir?","description":"Reduce-only emrin nasıl çalıştığını, istemeden ters pozisyon açmayı nasıl önlediğini ve ne zaman kullanılacağını öğrenin.","related":[["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["long-and-short","Long ve short pozisyon","Long pozisyon, fiyatın yükselmesinden kazanç sağlamak için açılan alış pozisyonudur; short pozisyon ise fiyatın düşmesinden kazanç sağlamak için açılan satış pozisyonudur."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Kâr al ve zarar durdur plandır, sigorta değil"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"tr","term":"Cüzdan adresi (wallet address)","aka":["kripto adresi","yatırma adresi","wallet address","alıcı adresi"],"short":"Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür.","body":[["Her ağın kendi adres biçimi vardır. ",["Bitcoin","bitcoin"]," adresleri genellikle 1, 3 veya bc1 ile başlar; ",["Ethereum","ethereum"],", BNB Smart Chain, Arbitrum gibi EVM uyumlu ağlarda adresler 0x ile başlar; Tron adresleri T ile başlar. Aynı 0x adresi birden fazla EVM ağında geçerli olabilir, bu da yanlış ağ seçimini kolaylaştırır."],[["Blokzincir","blockchain"]," işlemleri geri alınamaz. Adresteki tek bir karakter yanlışsa veya adres başka birine aitse, gönderdiğiniz varlığı geri istemenin genellikle bir yolu yoktur. Bu yüzden adresi elle yazmak yerine kopyalayıp yapıştırmak ve sonra baştaki ve sondaki karakterleri kontrol etmek önemlidir."],"Borsalar her kullanıcıya ve her ağa ayrı bir yatırma adresi verebilir. Bazı coinlerde (XRP, XLM, bazı borsa adresleri gibi) adresin yanında ayrıca bir memo veya etiket gerekir. Adresin hangi ağa ait olduğunu her zaman yatırma ekranında kontrol edin."],"example":["Borsadaki ",["USDT","usdt"]," bakiyenizden 800 USDT'yi kendi cüzdanınıza çekmek istiyorsunuz. Cüzdanınızdaki Tron adresi T ile başlıyor ve 34 karakter uzunluğunda. Çekim ekranında ağ olarak TRC20'yi seçer, adresi yapıştırır, ilk 4 ve son 4 karakteri karşılaştırırsınız. Önce 10 USDT'lik bir test transferi gönderir, ulaştığını görünce kalan 790 USDT'yi yollarsınız. Bu sırada iki ",["çekim ücreti","withdrawal-fee"]," ödersiniz, ama yanlış adres riskine karşı küçük bir sigorta gibidir."],"mistakes":["Adresin sadece ilk birkaç karakterini kontrol etmek.","Ağ türünü kontrol etmeden aynı görünen 0x adresine farklı bir ağdan göndermek.","İşlem geçmişinden adres kopyalamak; bu, adres zehirleme saldırılarına kapı açar."],"faq":[{"q":"Cüzdan adresimi paylaşmak güvenli mi?","a":"Evet, para almak için adres paylaşılır ve adresle fon çekilemez. Ancak adres herkese açık bir blokzincirde bakiyenizi ve geçmişinizi gösterebilir."},{"q":"Yanlış adrese gönderilen kripto geri alınabilir mi?","a":"Çoğu durumda hayır. Adres bir borsaya aitse destek ekibi bazen yardımcı olabilir, ancak bu garanti değildir ve ücret alınabilir."}],"title":"Cüzdan adresi nedir? Kripto adresi nasıl kontrol edilir?","description":"Kripto cüzdan adresinin ne olduğunu, ağlara göre biçimlerini ve transfer öncesi adresi nasıl kontrol edeceğinizi öğrenin.","related":[["blockchain-network","Yatırma ağı (ağ seçimi)","Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir."],["memo-tag","Memo / hedef etiketi (destination tag)","Memo veya hedef etiketi, bazı coinlerde borsaya yapılan bir yatırmanın hangi kullanıcıya ait olduğunu belirlemek için adresin yanında gönderilen ek koddur."],["address-poisoning","Adres zehirleme (address poisoning)","Adres zehirleme, dolandırıcının sizin sık kullandığınız adrese benzeyen bir adresten işlem geçmişinize küçük veya sıfır tutarlı transferler göndererek, bir sonraki transferinizde yanlış adresi kopyalamanızı sağlamaya çalıştığı saldırıdır."],["withdrawal-whitelist","Çekim beyaz listesi (withdrawal whitelist)","Çekim beyaz listesi, borsa hesabınızdan yalnızca önceden kaydedip onayladığınız adreslere kripto çekilmesine izin veren bir güvenlik ayarıdır."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"tr","term":"Oltalama (phishing)","aka":["phishing","kimlik avı","sahte site dolandırıcılığı"],"short":"Oltalama (phishing), dolandırıcıların sahte web siteleri, e-postalar, mesajlar veya reklamlar kullanarak sizden şifre, 2FA kodu, kurtarma ifadesi almaya ya da zararlı bir işlemi imzalatmaya çalıştığı saldırıdır.","body":[["Kriptoda oltalama birçok biçimde görülür: borsa adına gönderilen sahte e-postalar, arama motorunda reklam olarak öne çıkan sahte borsa siteleri, \"",["airdrop","airdrop"]," talep et\" bağlantıları, sahte cüzdan uygulamaları ve sosyal medyada destek ekibi gibi davranan hesaplar."],["Web3'te özellikle tehlikeli olan tür, sizden şifre değil işlem imzası isteyen sitelerdir. Bir sahte site \"bağlan\" veya \"talep et\" butonunun arkasına sınırsız ",["token onayı","token-approval"]," ya da varlık transferi gizleyebilir. Cüzdanınızın gösterdiği onay penceresini okumadan imzalarsanız, saldırgan fonlarınızı daha sonra çekebilir."],["Korunmanın temel adımları: borsaya her zaman yer imlerinden veya resmî uygulamadan girmek, alan adını harf harf kontrol etmek, ",["oltalama karşıtı kod","anti-phishing-code"]," kullanmak, kurtarma ifadenizi asla bir siteye yazmamak ve aceleye getiren mesajlara şüpheyle bakmaktır."]],"example":["Arama motorunda borsa adını yazıyorsunuz ve en üstte reklam olarak bir bağlantı çıkıyor. Alan adında bir harf farklı: gerçek adın sonundaki harf iki kez yazılmış. Bu sitede giriş yapıp ",["2FA","two-factor-authentication"]," kodunu girerseniz, saldırgan gerçek siteye eş zamanlı giriş yapabilir ve 900 ",["USDT","usdt"],"'lik bakiyenizi çekmeyi deneyebilir. Yer imini kullanarak gerçek siteye girerseniz bu risk ortadan kalkar."],"mistakes":["Arama sonuçlarındaki reklam bağlantılarından borsaya girmek.","Kurtarma ifadesini \"cüzdan doğrulama\" isteyen bir forma girmek.","Cüzdan onay penceresindeki izinleri okumadan imzalamak."],"faq":[{"q":"Oltalama sitesine giriş yaptım, ne yapmalıyım?","a":"Hemen gerçek sitede şifrenizi değiştirin, 2FA'yı yenileyin ve tüm oturumları kapatın. Cüzdanla imza attıysanız onayları iptal edin ve gerekirse fonları yeni bir cüzdana taşıyın."},{"q":"Sahte bir borsa sitesi nasıl anlaşılır?","a":"Alan adını dikkatle okuyun, yer imini kullanın ve borsanın resmî uygulamasındaki bilgilerle karşılaştırın. Aşırı aciliyet ve ödül vaatleri de tipik uyarı işaretleridir."}],"title":"Phishing (oltalama) nedir? Kripto dolandırıcılığından korunma","description":"Kriptoda oltalama saldırılarının türlerini, sahte site ve imza tuzaklarını ve kendinizi nasıl koruyacağınızı öğrenin.","related":[["anti-phishing-code","Oltalama karşıtı kod (anti-phishing code)","Oltalama karşıtı kod, borsa hesabınızda belirlediğiniz ve borsanın size gönderdiği gerçek e-postalarda görünen kişisel bir kelimedir; bu kodu içermeyen e-postaların sahte olma ihtimali yüksektir."],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."],["token-approval","Token onayı (token approval / allowance)","Token onayı, cüzdanınızdaki belirli bir token'ı sizin adınıza harcayabilmesi için bir akıllı sözleşmeye verdiğiniz izindir ve sınırsız verilen onaylar istismar edilirse cüzdanınızı boşaltabilir."],["address-poisoning","Adres zehirleme (address poisoning)","Adres zehirleme, dolandırıcının sizin sık kullandığınız adrese benzeyen bir adresten işlem geçmişinize küçük veya sıfır tutarlı transferler göndererek, bir sonraki transferinizde yanlış adresi kopyalamanızı sağlamaya çalıştığı saldırıdır."],["pig-butchering-scam","Domuz kasaplığı dolandırıcılığı (pig butchering)","Domuz kasaplığı dolandırıcılığı, dolandırıcının haftalarca güven veya romantik ilişki kurduktan sonra kurbanı sahte bir kripto yatırım platformuna para yatırmaya ikna ettiği ve sonunda tüm parayı aldığı uzun soluklu bir dolandırıcılıktır."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Gerçek kapıyı bul: Körlemesine hesap açma"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"tr","term":"Rezerv kanıtı (proof of reserves)","aka":["proof of reserves","PoR","rezerv ispatı"],"short":"Rezerv kanıtı (PoR), bir kripto borsasının kullanıcılarına ait bakiyeleri karşılayacak kadar varlığı gerçekten tuttuğunu, zincir üstü adresler ve kriptografik yöntemlerle göstermeye çalıştığı denetim raporudur.","body":["2022'deki FTX çöküşünden sonra birçok büyük borsa düzenli rezerv kanıtı yayınlamaya başladı. Tipik yöntem iki parçadan oluşur: borsa, sahip olduğu cüzdan adreslerini gösterir ve kullanıcı bakiyelerinin toplamını bir Merkle ağacıyla özetler. Siz de kendi bakiyenizin bu ağaca dahil edildiğini doğrulayabilirsiniz.","Rapor genellikle her varlık için bir rezerv oranı verir. Yüzde 100 veya üzeri, borsanın o varlıkta kullanıcı bakiyelerini karşılayacak kadar varlık tuttuğu anlamına gelir. Bu, borsa güvenilirliğini değerlendirmek için faydalı bir ipucudur.","Sınırları da vardır. Rezerv kanıtı çoğu zaman yalnızca varlıkları gösterir; borsanın tüm borçlarını veya o varlıkların başka bir yere teminat olarak verilip verilmediğini tam olarak göstermeyebilir. Rapor belirli bir anın görüntüsüdür ve yöntemler borsadan borsaya farklıdır. Bağımsız bir denetçinin katılıp katılmadığına bakmak önemlidir."],"example":["Bir borsanın raporunda kullanıcıların toplam ",["BTC","bitcoin"]," bakiyesi 20.000 BTC, borsanın gösterdiği adreslerdeki BTC ise 20.600 BTC olsun. Rezerv oranı 20.600 / 20.000 = yüzde 103 olur. Kendi hesabınızda 0,4 BTC varsa, borsanın doğrulama sayfasında kendi kaydınızın Merkle ağacına dahil olduğunu ve 0,4 BTC olarak listelendiğini kontrol edebilirsiniz."],"mistakes":["Yüzde 100 üzeri rezerv oranının borsanın hiçbir risk taşımadığını kanıtladığını sanmak.","Raporun tarihine bakmamak; eski bir rapor güncel durumu yansıtmayabilir.","Kendi bakiyenizin rapora dahil olup olmadığını hiç doğrulamamak."],"faq":[{"q":"Rezerv kanıtı borsanın güvenli olduğunu gösterir mi?","a":"Bir şeffaflık göstergesidir ama tam bir mali denetim değildir. Borçlar, yönetim ve düzenleme gibi başka faktörleri de dikkate almalısınız."},{"q":"Merkle ağacı ne işe yarar?","a":"Tüm kullanıcı bakiyelerini tek bir özet değere bağlar. Böylece kişisel verileri yayınlamadan, kendi bakiyenizin toplama dahil edildiğini doğrulayabilirsiniz."}],"title":"Rezerv kanıtı (proof of reserves) nedir?","description":"Borsaların rezerv kanıtını nasıl yayınladığını, rezerv oranının anlamını ve bu raporların sınırlarını öğrenin.","related":[["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."],["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."],["insurance-fund","Sigorta fonu (Insurance fund)","Sigorta fonu, vadeli işlem borsalarının tasfiye edilen pozisyonların teminatı aşan zararlarını karşılamak ve otomatik kaldıraç azaltmayı (ADL) önlemek için tuttuğu rezerv fondur."],["on-chain-analysis","Zincir üstü analiz (on-chain analiz)","Zincir üstü analiz, blockchain'de herkese açık kayıtlı işlemleri, adres hareketlerini ve borsa akışlarını inceleyerek piyasa davranışını anlamaya çalışan analiz yöntemidir."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Gerçek kapıyı bul: Körlemesine hesap açma"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"tr","term":"Kripto kazanç ürünleri (Earn)","aka":["Earn","Simple Earn","kripto birikim","esnek tasarruf"],"short":"Kripto kazanç (Earn) ürünleri, borsaların kullanıcıların coin'lerini esnek veya vadeli olarak yatırıp karşılığında faiz benzeri getiri almasını sağlayan birikim ve getiri ürünleridir.","body":["Borsalar bu ürünleri farklı isimlerle sunar: Simple Earn, esnek birikim, vadeli birikim gibi. Esnek üründe coin'inizi istediğiniz zaman çekebilirsiniz ama getiri genelde daha düşüktür ve sık değişir. Vadeli üründe belirli bir süre kilitlersiniz ve karşılığında genellikle daha yüksek oran alırsınız.",["Getiri birkaç kaynaktan gelebilir: ",["staking","staking"]," ödülleri, borç verme faizleri, vadeli piyasalara sağlanan ",["likidite","liquidity"]," veya borsanın promosyonları. Getiri genellikle ",["APR","apr-vs-apy"]," olarak gösterilir; bileşik getiri hesaplanıyorsa APY ile karşılaştırma yapmak gerekir."],"Coin'leriniz bu süre boyunca borsanın gözetiminde kalır. Risk, borsanın kendisine ve ürünün getiriyi nereden ürettiğine bağlıdır. Getirinin kaynağını, kilit süresini ve erken çıkış kurallarını okumak önemlidir."],"example":["Bir borsada 5.000 ",["USDT","usdt"],"'yi yıllık yüzde 6 APR veren 90 günlük vadeli ürüne yatırdığınızı varsayalım. Getiri basit faizle hesaplanırsa 5.000 x 0,06 x 90 / 365 = yaklaşık 73,97 USDT kazanırsınız. Aynı tutarı yüzde 3 veren esnek ürüne koysaydınız 90 günde yaklaşık 36,99 USDT kazanırdınız ama paranıza her an erişebilirdiniz. Vadeli üründen 45. günde çıkmak isterseniz bazı ürünlerde birikmiş getirinin tamamını kaybedebilirsiniz."],"mistakes":["Gösterilen yüksek oranın tüm tutar için geçerli olduğunu varsaymak; bazı oranlar sadece ilk birkaç yüz dolar içindir.","Kilitli üründe erken çıkış kurallarını okumamak.","Getirinin nereden geldiğini sormadan büyük bakiyeyi tek bir ürüne koymak."],"faq":[{"q":"Earn ürünleri güvenli mi?","a":"Risk, borsanın güvenilirliğine ve getirinin kaynağına bağlıdır. Coin'leriniz borsada kaldığı için borsa riskini taşırsınız; ayrıca vadeli ürünlerde erişim kısıtlıdır."},{"q":"Esnek ve vadeli birikim farkı nedir?","a":"Esnek birikimde coin'lerinizi istediğiniz zaman çekebilirsiniz, oran genelde daha düşüktür. Vadeli birikimde belirli süre kilitlersiniz ve karşılığında daha yüksek oran alabilirsiniz."}],"title":"Kripto Earn nedir? Borsada faiz ve birikim ürünleri","description":"Kripto Earn ürünleri nedir, esnek ve vadeli birikim nasıl çalışır, getiri nasıl hesaplanır ve hangi risklere dikkat etmelisiniz.","related":[["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["apr-vs-apy","APR ve APY farkı","APR, bileşik etki olmadan hesaplanan basit yıllık getiri oranıdır; APY ise kazancın düzenli olarak yeniden yatırıldığı varsayımıyla bileşik getiriyi gösterir, bu yüzden aynı oran için APY her zaman APR'den yüksek veya ona eşittir."],["dual-investment","Çift yatırım (dual investment)","Çift yatırım (dual investment), belirlenen vade sonunda fiyatın hedef fiyata göre konumuna bağlı olarak paranızı ya ana coin ya da stablecoin olarak, her iki durumda da ek getiriyle geri aldığınız opsiyon tabanlı bir üründür."],["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"tr","term":"P2P alım satım (C2C)","aka":["P2P","C2C","P2P işlem","eşten eşe alım satım"],"short":"P2P alım satım, kullanıcıların borsanın aracılık ettiği bir pazarda, kripto varlığı birbirlerinden banka transferi gibi ödeme yöntemleriyle doğrudan aldığı veya sattığı işlem türüdür.","body":["Satıcı bir ilan açar: fiyat, minimum ve maksimum tutar, kabul ettiği ödeme yöntemleri. Siz ilanı seçip sipariş verdiğinizde borsa satıcının coin'lerini emanette (escrow) kilitler. Siz parayı satıcının banka hesabına gönderirsiniz, satıcı ödemeyi onaylayınca coin'ler hesabınıza geçer.","P2P özellikle bankaların borsalarla doğrudan çalışmadığı veya yerel para birimiyle yatırma seçeneğinin sınırlı olduğu yerlerde yaygındır. Fiyat satıcıya göre değiştiği için piyasa kurundan biraz yüksek veya düşük olabilir.","Riskler çoğunlukla ödeme tarafındadır: ödeme yapmadan 'ödedim' butonuna basan alıcılar, üçüncü kişilerden gelen ve sonradan geri istenen ödemeler, platform dışına taşınmaya çalışılan konuşmalar. Yalnızca platformun sohbetini kullanın ve hesabınıza gelen paranın isminin sipariş sahibiyle aynı olduğunu kontrol edin."],"example":["P2P pazarında 20.000 TL ile ",["USDT","usdt"]," almak istediğinizi varsayalım. Satıcı 1 USDT için 40,60 TL istiyor; spot kur 40,00 TL. Siparişi açtığınızda yaklaşık 492,6 USDT emanete kilitlenir. 15 dakika içinde 20.000 TL'yi satıcının ilandaki adına kayıtlı hesaba gönderirsiniz. Satıcı onaylayınca USDT size geçer. Spot fiyatla 500 USDT alabilecekken yaklaşık 7,4 USDT fark ödemiş olursunuz; bu da P2P'nin kolaylık maliyetidir."],"mistakes":["Parayı göndermeden önce siparişi açmamak veya platform dışında anlaşmak.","Satış yaparken ödemenin geldiğini banka uygulamasından değil ekran görüntüsünden kontrol etmek.","Ödeme açıklamasına 'kripto' ya da 'USDT' gibi notlar yazmak isteyen veya farklı isimden ödeme yapan karşı taraflarla işlem yapmak."],"faq":[{"q":"P2P işlem güvenli mi?","a":"Borsanın emanet sistemi coin tarafını korur, ancak ödeme tarafındaki dolandırıcılıklar hâlâ mümkündür. Yalnızca platform içinde iletişim kurun ve gelen ödemenin adını mutlaka kontrol edin."},{"q":"P2P'de fiyat neden spot kurdan farklı?","a":"Her satıcı kendi fiyatını belirler ve ödeme kolaylığı, hız ve risk için bir fark ekler. Bu yüzden P2P kuru genellikle spot kurdan biraz farklıdır."}],"title":"P2P kripto alım satım nedir? C2C nasıl çalışır","description":"P2P (C2C) kripto alım satım nedir, emanet sistemi nasıl işler, fiyat farkı nasıl hesaplanır ve ödeme dolandırıcılığından nasıl korunursunuz.","related":[["fiat-on-ramp","Fiat giriş kanalı (fiat on-ramp)","Fiat giriş kanalı (on-ramp), Türk lirası, dolar veya euro gibi geleneksel parayı kripto varlığa çevirmenizi sağlayan yol ya da hizmettir; banka havalesi, kartla alım ve P2P bunun örnekleridir."],["usdt","USDT (Tether)","USDT (Tether), Tether şirketi tarafından çıkarılan, değerini 1 ABD dolarına sabitlemeyi amaçlayan ve kripto piyasalarında en yaygın kullanılan stablecoin'dir."],["pig-butchering-scam","Domuz kasaplığı dolandırıcılığı (pig butchering)","Domuz kasaplığı dolandırıcılığı, dolandırıcının haftalarca güven veya romantik ilişki kurduktan sonra kurbanı sahte bir kripto yatırım platformuna para yatırmaya ikna ettiği ve sonunda tüm parayı aldığı uzun soluklu bir dolandırıcılıktır."],["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"İlk para yatırma: Para nereden gelir ve nereye gider?"},"coin":null,"tool":null,"cta":true}});
